// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "img_91", fn: function(){ return ((dma_inspectionResult.get("valid") ?? (() => { throw new Error("unresolved:" + "inspectionResult.valid"); })())); } }, { id: "img_92", fn: function(){ return ((dma_inspectionResult.get("valid") ?? (() => { throw new Error("unresolved:" + "inspectionResult.valid"); })())); } }, { id: "c_otherwise_93", fn: function(){ return (!(((dma_inspectionResult.get("valid") ?? (() => { throw new Error("unresolved:" + "inspectionResult.valid"); })())))); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

