/**
 * @event
 * @name scwin.grd_inspectionResultDocumentErrors_3_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_inspectionResultDocumentErrors_3_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_inspectionResultDocumentErrors');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_inspectionResultDocumentErrors'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.focusError === 'function') { scwin.focusError(r["formCd"], r["formVer"], r["formDiv"], r["xpath"]); } else { console.error('[sdd] 행 동작 미정의: scwin.focusError (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.focusError'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_inspectionResultDocumentErrors_3.oncellclick' });
    }
};

/**
 * @event
 * @name scwin.img_91_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_91_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_91_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.submit()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00007.img_91_onclick' }); }
};

