*/
scwin.focusError = function (formCd, formVer, wrtrptMaindocTpCd, xpath) {
    /* sdd-asis-lifecycle:begin focusError — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const nsArray = eval("getNamespaces_" + formCd + "()");
    (((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})) !== scwin && typeof (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})).focusError === 'function' ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { console.error('[sdd] 부모 화면 스코프 없음 — ' + id + ' 를 못 읽는다(단독 진입이거나 부모가 닫혔다)'); return null; }, scwin: {} }).scwin || {})).focusError(formCd, formVer, wrtrptMaindocTpCd, xpath, nsArray) : void 0), $c.win.closePopup([formCd, formVer, wrtrptMaindocTpCd, xpath, nsArray]));
    /* sdd-asis-lifecycle:end */
};


/**
